#!/usr/bin/env bash
# ==============================================================================
# All-in-One Self-Contained Workload Deployment Engine for k3s
# Deploys:
#   1. cert-manager v1.17 & ClusterIssuers
#   2. Forgejo Git Forge (with native Actions)
#   3. Forgejo DinD Runner (StatefulSet + Docker-in-Docker sidecar)
#   4. Plane Community Edition (plane.so Management Platform)
#   5. It's a Plan (itsaplan.dev AI Issue Tracker)
#
# Fully self-contained:
#   - ZERO external Helm chart or manifest dependencies
#   - Works 100% offline with pre-imported images
#   - Explicitly enforces imagePullPolicy: IfNotPresent for air-gap resilience
#   - Piped curl-safe (safe for: curl -fsSL <URL> | sudo bash)
#
# Usage:
#   sudo ./deploy-workloads.sh
#   sudo ./deploy-workloads.sh --domain example.com --admin-pass SecretPass123!
# ==============================================================================
set -eo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" 2>/dev/null && pwd || echo "${PWD}")"

RED='\033[0;31m'
GREEN='\033[0;32m'
BLUE='\033[0;34m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
BOLD='\033[1m'
NC='\033[0m'

log_step() { echo -e "\n${BLUE}${BOLD}==>${NC} ${BOLD}$1${NC}"; }
log_info() { echo -e "${CYAN}   ℹ ${NC}$1"; }
log_success() { echo -e "${GREEN}   ✔ ${NC}$1"; }
log_warn() { echo -e "${YELLOW}   ⚠ ${NC}$1"; }
log_error() { echo -e "${RED}   ✖ ERROR: ${NC}$1" >&2; }

DOMAIN="${DOMAIN:-}"
TARGET_IP="${TARGET_IP:-${IP:-}}"
IFACE="${IFACE:-eth0}"
ADMIN_PASS="${ADMIN_PASS:-${ADMIN_PASSWORD:-}}"
TLS_MODE="${TLS_MODE:-${TLS:-}}"
ACME_EMAIL="${ACME_EMAIL:-${EMAIL:-}}"

while [[ $# -gt 0 ]]; do
    case "$1" in
        -d|--domain)
            DOMAIN="$2"; shift 2 ;;
        -i|--ip)
            TARGET_IP="$2"; shift 2 ;;
        --iface)
            IFACE="$2"; shift 2 ;;
        -p|--admin-pass|--admin-password)
            ADMIN_PASS="$2"; shift 2 ;;
        -t|--tls)
            TLS_MODE="$2"; shift 2 ;;
        -e|--email)
            ACME_EMAIL="$2"; shift 2 ;;
        -h|--help)
            cat << 'EOF'
Usage: ./deploy-workloads.sh [OPTIONS]

Options:
  -d, --domain <DOMAIN>       Base domain name (default: auto-detected <IP>.nip.io)
  -i, --ip <IP>               Host IP address for Ingress (default: auto-detect eth0)
  --iface <IFACE>             Network interface to extract IP from (default: eth0)
  -p, --admin-pass <PASSWORD> Master administrator password (default: random secure string)
  -t, --tls <MODE>            TLS mode: 'selfsigned', 'letsencrypt' (default: auto)
  -e, --email <EMAIL>         ACME email for Let's Encrypt
  -h, --help                  Show this help message and exit
EOF
            exit 0
            ;;
        *)
            log_warn "Unknown argument: $1"; shift ;;
    esac
done

echo -e "${CYAN}${BOLD}"
cat << 'EOF'
  _  _________      __            _     _                 _     
 | |/ /___ / ___   / /_      ___ | | __| | ___   __ _  __| |___ 
 | ' /  |_ \/ __| | '_ \    / _ \| |/ / _` / _ \ / _` |/ _` / __|
 | . \ ___) \__ \ | (_) |  | (_) |   < (_| (_) | (_| | (_| \__ \
 |_|\_\____/|___/  \___/    \___/|_|\_\__,_\___/ \__,_|\__,_|___/
EOF
echo -e " Autonomous Workload Deployment Engine (Air-Gap Resilient Manifest Applier)${NC}\n"

# ------------------------------------------------------------------------------
# 1. Environment & Kubernetes Readiness Verification
# ------------------------------------------------------------------------------
log_step "[1/6] Verifying Kubernetes Environment..."

if [ "${EUID:-$(id -u)}" -ne 0 ]; then
    log_warn "Running without root privileges. Ensure kubectl has cluster-admin access."
fi

# Ensure kubeconfig is active
if [ -f /etc/rancher/k3s/k3s.yaml ] && [ -z "${KUBECONFIG:-}" ]; then
    export KUBECONFIG=/etc/rancher/k3s/k3s.yaml
elif [ -f /root/.kube/config ] && [ -z "${KUBECONFIG:-}" ]; then
    export KUBECONFIG=/root/.kube/config
fi

# Locate kubectl
if ! command -v kubectl >/dev/null 2>&1; then
    for kbin in /usr/local/bin/kubectl /usr/bin/kubectl /usr/local/bin/k3s /usr/bin/k3s; do
        if [ -x "$kbin" ]; then
            if [[ "$kbin" == *k3s ]]; then
                kubectl() { "$kbin" kubectl "$@"; }
                export -f kubectl 2>/dev/null || true
            else
                export PATH="$(dirname "$kbin"):$PATH"
            fi
            break
        fi
    done
fi

if ! kubectl get nodes >/dev/null 2>&1; then
    log_error "Cannot connect to Kubernetes API server! Check: sudo systemctl status k3s"
    exit 1
fi
NODE_NAME=$(kubectl get nodes --no-headers | awk '{print $1}' | head -n 1)
log_success "Kubernetes cluster is reachable (Node: ${NODE_NAME})"

# Auto-detect Host IP (prioritizing eth0) and Domain
if [ -z "${TARGET_IP}" ]; then
    # 1. Check specified interface
    if [ -n "${IFACE}" ]; then
        TARGET_IP=$(ip -4 addr show dev "${IFACE}" 2>/dev/null | awk '/inet /{print $2}' | cut -d/ -f1 | head -n 1 || true)
    fi
    # 2. Check eth0 explicitly
    if [ -z "${TARGET_IP}" ]; then
        TARGET_IP=$(ip -4 addr show dev eth0 2>/dev/null | awk '/inet /{print $2}' | cut -d/ -f1 | head -n 1 || true)
    fi
    # 3. Fallback to route or public queries
    if [ -z "${TARGET_IP}" ]; then
        TARGET_IP=$(curl -s --tlsv1.2 --tls-max 1.2 --connect-timeout 3 https://ifconfig.me 2>/dev/null || \
                    curl -s --tlsv1.2 --tls-max 1.2 --connect-timeout 3 https://api.ipify.org 2>/dev/null || \
                    ip route get 1.1.1.1 2>/dev/null | awk '{print $7}' | tr -d ' \n' || \
                    hostname -I 2>/dev/null | awk '{print $1}' || echo "")
    fi
fi

if [[ "${TARGET_IP}" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
    log_info "Target Ingress Host IP: ${TARGET_IP} (Interface: ${IFACE:-eth0})"
    if [ -z "${DOMAIN}" ]; then
        DOMAIN="${TARGET_IP}.nip.io"
        log_info "Base domain configured to: ${DOMAIN}"
    fi

    # Explicitly patch Traefik Service so all Ingresses show and route to this IP
    log_info "Configuring Traefik Ingress Controller to advertise IP ${TARGET_IP}..."
    kubectl patch svc traefik -n kube-system --type merge -p "{\"spec\":{\"externalIPs\":[\"${TARGET_IP}\"]}}" 2>/dev/null || true

    # Persist node-ip and flannel-iface to /etc/rancher/k3s/config.yaml if writable
    if [ -f /etc/rancher/k3s/config.yaml ] && [ -w /etc/rancher/k3s/config.yaml ]; then
        if ! grep -q "node-ip: \"${TARGET_IP}\"" /etc/rancher/k3s/config.yaml; then
            sed -i '/node-ip:/d;/node-external-ip:/d;/flannel-iface:/d' /etc/rancher/k3s/config.yaml 2>/dev/null || true
            cat << EOF >> /etc/rancher/k3s/config.yaml
node-ip: "${TARGET_IP}"
node-external-ip: "${TARGET_IP}"
flannel-iface: "${IFACE:-eth0}"
EOF
            log_info "Saved node-ip: ${TARGET_IP} and flannel-iface: ${IFACE:-eth0} to /etc/rancher/k3s/config.yaml"
        fi
    fi
else
    if [ -z "${DOMAIN}" ]; then
        DOMAIN="127.0.0.1.nip.io"
        log_warn "Could not determine host IP, defaulting domain to: ${DOMAIN}"
    fi
fi

if [ -z "${ADMIN_PASS}" ]; then
    ADMIN_PASS=$(head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n' | head -c 16)
    ADMIN_PASS="${ADMIN_PASS}A1!"
fi

CERT_ISSUER="selfsigned-issuer"
if [ "${TLS_MODE}" = "letsencrypt" ]; then
    CERT_ISSUER="letsencrypt-prod"
    ACME_EMAIL="${ACME_EMAIL:-admin@${DOMAIN}}"
fi

BETTER_AUTH_SECRET=$(head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')
APP_ENCRYPTION_KEY=$(head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')
PLANE_SECRET_KEY="plane-secret-$(head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n')"

log_info "Domain:        ${DOMAIN}"
log_info "TLS Issuer:    ${CERT_ISSUER}"
log_info "Master Pass:   ${ADMIN_PASS}"

# Ensure target namespaces exist
log_info "Creating target namespaces..."
for ns in cert-manager forgejo forgejo-runner plane itsaplan; do
    kubectl create namespace "$ns" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
done

# ------------------------------------------------------------------------------
# Helper function to decode and apply embedded templates
# ------------------------------------------------------------------------------
apply_manifest() {
    local b64_input="$1"
    echo "$b64_input" | base64 -d | gzip -d | \
        sed -e "s|__DOMAIN__|${DOMAIN}|g" \
            -e "s|__ADMIN_PASS__|${ADMIN_PASS}|g" \
            -e "s|__CERT_ISSUER__|${CERT_ISSUER}|g" \
            -e "s|__ACME_EMAIL__|${ACME_EMAIL:-admin@${DOMAIN}}|g" \
            -e "s|__BETTER_AUTH_SECRET__|${BETTER_AUTH_SECRET}|g" \
            -e "s|__APP_ENCRYPTION_KEY__|${APP_ENCRYPTION_KEY}|g" \
            -e "s|__PLANE_SECRET_KEY__|${PLANE_SECRET_KEY}|g" | \
        kubectl apply -f -
}

# ------------------------------------------------------------------------------
# 2. Deploy cert-manager & ClusterIssuers
# ------------------------------------------------------------------------------
log_step "[2/6] Deploying cert-manager & TLS ClusterIssuers..."
apply_manifest ""

cat << EOF | kubectl apply -f -
apiVersion: cert-manager.io/v1
kind: ClusterIssuer
metadata:
  name: selfsigned-issuer
spec:
  selfSigned: {}
---
apiVersion: cert-manager.io/v1
kind: ClusterIssuer
metadata:
  name: letsencrypt-prod
spec:
  acme:
    server: https://acme-v02.api.letsencrypt.org/directory
    email: "${ACME_EMAIL:-admin@${DOMAIN}}"
    privateKeySecretRef:
      name: letsencrypt-prod-account-key
    solvers:
      - http01:
          ingress:
            ingressClassName: traefik
EOF
log_success "cert-manager resources submitted."

# ------------------------------------------------------------------------------
# 3. Deploy Forgejo (Git Forge)
# ------------------------------------------------------------------------------
log_step "[3/6] Deploying Forgejo (Git Forge)..."
apply_manifest ""
log_success "Forgejo Git server submitted."

# ------------------------------------------------------------------------------
# 4. Deploy Forgejo CI/CD DinD Runner
# ------------------------------------------------------------------------------
log_step "[4/6] Deploying Forgejo Actions Runner (with DinD sidecar)..."

log_info "Waiting for Forgejo to be ready to generate runner token..."
FORGEJO_POD=""
for i in $(seq 1 45); do
    FORGEJO_POD=$(kubectl get pods -n forgejo -l app.kubernetes.io/name=forgejo -o jsonpath="{.items[0].metadata.name}" 2>/dev/null || true)
    if [ -n "$FORGEJO_POD" ]; then
        READY=$(kubectl get pod -n forgejo "$FORGEJO_POD" -o jsonpath="{.status.containerStatuses[0].ready}" 2>/dev/null || true)
        if [ "$READY" = "true" ]; then
            break
        fi
    fi
    sleep 2
done

RUNNER_TOKEN=""
if [ -n "$FORGEJO_POD" ]; then
    log_info "Generating Actions Runner token from Forgejo CLI..."
    for i in $(seq 1 15); do
        RUNNER_TOKEN=$(kubectl exec -n forgejo "$FORGEJO_POD" -c forgejo -- gitea actions generate-runner-token 2>/dev/null || \
                      kubectl exec -n forgejo "$FORGEJO_POD" -c forgejo -- forgejo actions generate-runner-token 2>/dev/null || true)
        RUNNER_TOKEN=$(echo "$RUNNER_TOKEN" | tr -d "[:space:]")
        if [ -n "$RUNNER_TOKEN" ]; then
            log_success "Obtained real Actions Runner registration token."
            break
        fi
        sleep 2
    done
fi

if [ -z "$RUNNER_TOKEN" ]; then
    log_warn "Could not fetch runner token from Forgejo yet; using bootstrap placeholder."
    RUNNER_TOKEN="initial-bootstrap-token"
fi

kubectl create secret generic forgejo-runner-secret \
    --namespace forgejo-runner \
    --from-literal=token="${RUNNER_TOKEN}" \
    --dry-run=client -o yaml | kubectl apply -f - >/dev/null

kubectl delete statefulset forgejo-runner -n forgejo-runner --cascade=orphan --ignore-not-found=true 2>/dev/null || true
apply_manifest ""
log_success "Forgejo Actions DinD runner submitted."

# ------------------------------------------------------------------------------
# 5. Deploy Plane Community Edition (plane.so)
# ------------------------------------------------------------------------------
log_step "[5/6] Deploying Plane Project Management Platform..."
kubectl delete job plane-app-minio-bucket-1 plane-app-api-migrate-1 -n plane --ignore-not-found=true 2>/dev/null || true
kubectl delete job plane-app-minio-bucket-1 plane-app-api-migrate-1 -n plane --ignore-not-found=true 2>/dev/null || true
apply_manifest ""
log_success "Plane CE submitted."

# ------------------------------------------------------------------------------
# 6. Deploy It's a Plan (itsaplan.dev)
# ------------------------------------------------------------------------------
log_step "[6/6] Deploying It's a Plan AI Issue Tracker..."
cat << EOF | kubectl apply -f -
apiVersion: v1
kind: Secret
metadata:
  name: itsaplan-secrets
  namespace: itsaplan
type: Opaque
stringData:
  POSTGRES_USER: "itsaplan"
  POSTGRES_PASSWORD: "${ADMIN_PASS}"
  POSTGRES_DB: "itsaplan"
  DATABASE_URL: "postgres://itsaplan:${ADMIN_PASS}@itsaplan-postgres:5432/itsaplan"
  S3_ACCESS_KEY_ID: "rustfs-admin"
  S3_SECRET_ACCESS_KEY: "${ADMIN_PASS}"
  S3_BUCKET: "planner-attachments"
  BETTER_AUTH_SECRET: "${BETTER_AUTH_SECRET}"
  APP_ENCRYPTION_KEY: "${APP_ENCRYPTION_KEY}"
  API_URL: "https://api.itsaplan.${DOMAIN}"
  APP_URL: "https://itsaplan.${DOMAIN}"
  BETTER_AUTH_URL: "https://api.itsaplan.${DOMAIN}"
  BETTER_AUTH_TRUSTED_ORIGINS: "https://itsaplan.${DOMAIN},http://itsaplan.${DOMAIN}"
EOF

kubectl delete job itsaplan-bucket-init itsaplan-db-migrate -n itsaplan --ignore-not-found=true 2>/dev/null || true
apply_manifest ""
log_success "It's a Plan submitted."

# ------------------------------------------------------------------------------
# Verification & Live Status Check
# ------------------------------------------------------------------------------
echo ""
echo -e "${BLUE}${BOLD}==============================================================================${NC}"
echo -e "${BLUE}${BOLD}              🎉 ALL WORKLOADS SUBMITTED TO KUBERNETES!${NC}"
echo -e "${BLUE}${BOLD}==============================================================================${NC}\n"

log_info "Force-refreshing any pods previously stuck in ImagePullBackOff..."
for ns in cert-manager forgejo forgejo-runner plane itsaplan; do
    FAILED_PODS=$(kubectl get pods -n "$ns" --no-headers 2>/dev/null | grep -E "(ImagePullBackOff|ErrImagePull|Init:ImagePullBackOff|Init:ErrImagePull|CrashLoopBackOff|Error)" | awk '{print $1}' || true)
    if [ -n "${FAILED_PODS}" ]; then
        log_info "Restarting stuck pods in '${ns}': ${FAILED_PODS}"
        echo "${FAILED_PODS}" | xargs kubectl delete pod -n "$ns" --grace-period=0 --force >/dev/null 2>&1 || true
    fi
done

log_info "Waiting 10 seconds for initial container initialization..."
sleep 10

echo ""
for ns in cert-manager forgejo forgejo-runner plane itsaplan; do
    echo -e "${CYAN}${BOLD}=== Namespace: ${ns} ===${NC}"
    kubectl get pods -n "$ns" -o wide || true
    echo ""
done

echo -e "${GREEN}${BOLD}==============================================================================${NC}"
echo -e "${GREEN}${BOLD}                           ACCESS & CREDENTIALS${NC}"
echo -e "${GREEN}${BOLD}==============================================================================${NC}"
echo -e " Base Domain:           ${BOLD}${DOMAIN}${NC}"
echo -e " Master Admin Password: ${BOLD}${ADMIN_PASS}${NC}"
echo ""
echo -e " 🚀 ${BOLD}Forgejo Git:${NC}        https://git.${DOMAIN}"
echo -e "    Username:           forgejo-admin"
echo -e "    Password:           ${ADMIN_PASS}"
echo -e "    SSH Clone Port:     32222"
echo ""
echo -e " 📋 ${BOLD}Plane.so Platform:${NC}  https://plane.${DOMAIN}"
echo -e "    First-Time Setup:   https://plane.${DOMAIN}/god-mode"
echo -e "    Suggested Email:    admin@${DOMAIN}"
echo -e "    Suggested Password: ${ADMIN_PASS}"
echo ""
echo -e " 🤖 ${BOLD}It's a Plan:${NC}        https://itsaplan.${DOMAIN}"
echo -e "    First-Time Setup:   Click 'Sign Up' to register on first visit"
echo -e "    API Endpoint:       https://api.itsaplan.${DOMAIN}"
echo -e "    Suggested Email:    admin@${DOMAIN}"
echo -e "    Suggested Password: ${ADMIN_PASS}"
echo -e "${GREEN}${BOLD}==============================================================================${NC}\n"
